CREATE TABLE IF NOT EXISTS produtos (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome VARCHAR(150) NOT NULL, preco_referencia DECIMAL(16,2) NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS componentes (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, produto_id BIGINT NOT NULL, pai_id BIGINT NULL, nome VARCHAR(150) NOT NULL, quantidade INT NOT NULL, custo_unitario DECIMAL(16,2) NOT NULL, CONSTRAINT fk_produto FOREIGN KEY (produto_id) REFERENCES produtos(id) ON DELETE CASCADE, CONSTRAINT fk_pai FOREIGN KEY (pai_id) REFERENCES componentes(id) ON DELETE CASCADE);
